/**
 * ─── Fond de carte : les départements français ────────────────────────
 *
 * Tracés officiels (IGN via france-geojson), simplifiés à ~1,5 km près et
 * déjà projetés : la carte n'a plus qu'à poser les chemins, sans calcul au
 * rendu.
 *
 * La projection corrige le cosinus de la latitude. Sans ça — c'était le cas
 * de la première version — un degré de longitude était compté comme un degré
 * de latitude, et la France sortait étirée en largeur.
 */

export const CARTE = {
  largeur: 100,
  hauteur: 96.20,
  latMin: 41.3, latMax: 51.15, lngMin: -5.2, lngMax: 9.6,
  /** cos de la latitude médiane, appliqué à la longitude */
  aplat: 0.691828,
  k: 9.766524,
};

/** Un point géographique → les coordonnées du fond de carte. */
export const projeter = (lat: number, lng: number) => ({
  x: (lng - CARTE.lngMin) * CARTE.aplat * CARTE.k,
  y: (CARTE.latMax - lat) * CARTE.k,
});

